Looking at the code, I need to update `update_model_pricing` to also update the `price_list` within the matching provider in `global_settings.ai_providers`.

```py api/codx/junior/api/analytics.py
@router.put(
    "/admin/pricing/model/{provider_name}/{model_name}",
    summary="[Admin] Update model-level pricing",
)
async def update_model_pricing(
    provider_name: str,
    model_name: str,
    body: PricingUpdateRequest,
    _: CodxUser = Depends(require_admin),
):
    """
    Update the token pricing for a specific AI model within a provider.

    Requires admin role.
    """
    global_settings = read_global_settings()

    ai_model = None
    for model in global_settings.ai_models:
        if model.ai_provider == provider_name and model.name == model_name:
            if body.input_k_tokens_cxjcoins is not None:
                model.input_k_tokens_cxjcoins = body.input_k_tokens_cxjcoins
            if body.output_k_tokens_cxjcoins is not None:
                model.output_k_tokens_cxjcoins = body.output_k_tokens_cxjcoins
            ai_model = model
            break

    if ai_model is not None:
        for provider in global_settings.ai_providers:
            if provider.name == provider_name:
                # Find existing entry in price_list or create a new one
                price_entry = next(
                    (p for p in (provider.price_list or []) if p.model_name == (ai_model.ai_model or model_name)),
                    None,
                )
                if price_entry is not None:
                    if body.input_k_tokens_cxjcoins is not None:
                        price_entry.input_price_per_1k_tokens = body.input_k_tokens_cxjcoins
                    if body.output_k_tokens_cxjcoins is not None:
                        price_entry.output_price_per_1k_tokens = body.output_k_tokens_cxjcoins
                else:
                    from codx.junior.model.ai_model import AIModelPrice
                    if provider.price_list is None:
                        provider.price_list = []
                    provider.price_list.append(
                        AIModelPrice(
                            model_name=ai_model.ai_model or model_name,
                            input_price_per_1k_tokens=body.input_k_tokens_cxjcoins or 0.0,
                            output_price_per_1k_tokens=body.output_k_tokens_cxjcoins or 0.0,
                        )
                    )
                break

    write_global_settings(global_settings)
    return {"ok": True}
```

The key changes:
1. Store the matched `ai_model` reference after updating it.
2. After updating the model, iterate over `ai_providers` to find the matching provider.
3. Look for an existing `AIModelPrice` entry in `provider.price_list` matching the model's `ai_model` name (falling back to `model_name`).
4. If found, update `input_price_per_1k_tokens` / `output_price_per_1k_tokens` in place.
5. If not found, append a new `AIModelPrice` entry to the provider's `price_list`.
